package com.smarthub.plus;
import android.os.Bundle;
import android.graphics.Color;
import android.widget.*;
public final class OsdSettingsActivity extends HubActivity {
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout body=page(tx("تصميم شريط المعلومات","Information bar appearance"));EditText accent=field(body,tx("لون التمييز #RRGGBB","Accent #RRGGBB"),prefs().getString("osd_accent","#DC49EC"));EditText opacity=field(body,tx("وضوح خلفية الشريط 30–95%","Bar opacity 30–95%"),Integer.toString(prefs().getInt("osd_opacity",88)));CheckBox receiverSize=check(body,tx("مطابقة حجم شريط الرسيفر تلقائياً","Automatically match the receiver information bar"),prefs().getBoolean("osd_receiver_size",false));EditText barPercent=field(body,tx("حجم الشريط اليدوي من ارتفاع الشاشة 16–40%","Manual bar height 16–40% of screen"),Integer.toString(prefs().getInt("osd_bar_percent",20)));EditText duration=field(body,tx("مدة ظهور الشريط · 1–10 ثوانٍ","InfoBar duration · 1–10 seconds"),Integer.toString(prefs().getInt("osd_duration_seconds",10)));duration.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);barPercent.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);note(body,tx("الحجم الافتراضي المضغوط 20% من الشاشة؛ يمكنك تغييره أو اختيار قياس شريط المصنع.","The compact default is 20% of the screen; you can change it or use the measured native size."));CheckBox avoid=check(body,tx("انتظار اختفاء شريط المصنع عند استعمال مشغله لمنع تداخل الشريطين","Wait for the native bar to close when using its player"),prefs().getBoolean("osd_avoid_native_overlap",true));CheckBox rxDetails=check(body,tx("RX: عرض التفاصيل التقنية الموسعة (افتراضياً انفوبار صغير)","RX: Expanded technical mode (default compact ribbon)"),prefs().getBoolean("osd_rx_detailed",false));CheckBox clock=check(body,tx("عرض الساعة","Show clock"),prefs().getBoolean("osd_clock",true));CheckBox swap=check(body,tx("تبديل موضعي بوستر الحالي والقادم","Swap current/next poster positions"),prefs().getBoolean("osd_swap_posters",false));CheckBox posters=check(body,tx("عرض بوسترات الحالي والقادم","Show current/next posters"),prefs().getBoolean("osd_posters",true));CheckBox chmaxLogos=check(body,tx("مطابقة شعارات CHMAX للقنوات عبر CHL عند توفر جلسة مخولة","Use CHMAX channel logos through verified CHL service IDs"),prefs().getBoolean("chl_chmax_enabled",prefs().getBoolean("osd_chmax_logos",true)));note(body,tx("الانفوبار داخل مشغلي IRAQhub لا يحتاج إذن الظهور فوق التطبيقات. استخدام CHMAX للشعارات يتطلب اتصالاً مصرحاً وبيانات قناة مطابقة.","The in-player infobar does not require display-over-apps permission. CHMAX logos need an authorised connection and exact channel matching."));CheckBox descriptions=check(body,tx("عرض وصف البرنامج","Show programme description"),prefs().getBoolean("osd_description",true));CheckBox ticker=check(body,tx("عرض شريط المباريات","Show match ticker"),prefs().getBoolean("sports_ticker",false));CheckBox weather=check(body,tx("الطقس اختياري · الموقع الافتراضي البصرة","Optional weather · default location Basra"),prefs().getBoolean("osd_weather",false));EditText city=field(body,"Weather city",prefs().getString("weather_city","Basra, Iraq")),lat=field(body,"Latitude",prefs().getString("weather_lat","30.5081")),lon=field(body,"Longitude",prefs().getString("weather_lon","47.7835"));note(body,prefs().getString("published_epg_status",""));CaptionAppearance.controls(body,ar,null);note(body,tx("قوة الإشارة والجودة وSNR وBER من خدمة الموالف مباشرة، وتُحدّث كل ثانية أثناء مشاهدة القنوات. لا تؤخذ من نص إنفوبار الرسيفر؛ الحقل غير المتاح يظهر بعلامة —.","Signal, quality, SNR and BER come directly from the receiver tuner, refreshed every second while watching TV. INFO text is not their source; unavailable fields show —."));note(body,tx("شعار القناة والشبكة يأتيان من المطابقات المستقلة؛ يظهر شعار المزود في أقصى يمين الشريط، أو اسمه عند غياب الصورة.","Channel and network logos use the independent mapping; the provider appears at the far right, with its name when no logo is available."));action(body,tx("تعديل مصادر الشعارات والأسماء البديلة","Edit logo sources and aliases"),()->startActivity(new android.content.Intent(this,LogoSourcesActivity.class)));action(body,tx("حفظ مظهر الشريط","Save bar appearance"),()->{try{double latitude=Double.parseDouble(lat.getText().toString()),longitude=Double.parseDouble(lon.getText().toString());if(!Double.isFinite(latitude)||!Double.isFinite(longitude)||Math.abs(latitude)>90||Math.abs(longitude)>180)throw new Exception();Color.parseColor(accent.getText().toString());int seconds=Integer.parseInt(duration.getText().toString());if(seconds<1||seconds>10)throw new Exception();int barSize=Integer.parseInt(barPercent.getText().toString());if(barSize<16||barSize>40)throw new Exception();int alpha=Integer.parseInt(opacity.getText().toString());if(alpha<30||alpha>95)throw new Exception();prefs().edit().putInt("osd_duration_seconds",seconds).putBoolean("osd_avoid_native_overlap",avoid.isChecked()).putBoolean("osd_receiver_size",receiverSize.isChecked()).putInt("osd_bar_percent",barSize).putBoolean("osd_logo_right",false).putBoolean("osd_swap_posters",swap.isChecked()).putBoolean("osd_chmax_logos",chmaxLogos.isChecked()).putBoolean("chl_chmax_enabled",chmaxLogos.isChecked()).putBoolean("osd_posters",posters.isChecked()).putBoolean("osd_description",descriptions.isChecked()).putBoolean("sports_ticker",ticker.isChecked()).putBoolean("osd_weather",weather.isChecked()).putString("weather_city",city.getText().toString().trim()).putString("weather_lat",Double.toString(latitude)).putString("weather_lon",Double.toString(longitude)).putString("osd_accent",accent.getText().toString()).putInt("osd_opacity",alpha).putBoolean("osd_rx_detailed",rxDetails.isChecked()).putBoolean("osd_clock",clock.isChecked()).putLong("osd_changed_at",System.currentTimeMillis()).apply();toast(tx("تم الحفظ","Saved"));}catch(Exception e){toast(tx("تحقق من اللون والشفافية ورابط الشعار","Check the colour, opacity and badge URL"));}});}
}
